// Entity – internal, mapped by EF Core
public class User
{
    public int Id { get; set; }
    public string Email { get; set; } = default!;
    public string PasswordHash { get; set; } = default!;   // must never leave the server
    public bool IsAdmin { get; set; }                      // must never be client-settable
    public DateTime CreatedAt { get; set; }
    public List<Order> Orders { get; set; } = [];          // would cause cycles / N+1
}

// Request DTO – only what a client may send (no IsAdmin → no over-posting)
public sealed record CreateUserRequest(string Email, string Password);

// Response DTO – only what a client should see, flattened
public sealed record UserResponse(int Id, string Email, int OrderCount, DateTime CreatedAt);

app.MapPost("/users", async (CreateUserRequest req, AppDbContext db, IPasswordHasher<User> hasher) =>
{
    var user = new User { Email = req.Email, CreatedAt = DateTime.UtcNow };
    user.PasswordHash = hasher.HashPassword(user, req.Password);

    db.Users.Add(user);
    await db.SaveChangesAsync();

    return Results.Created($"/users/{user.Id}",
        new UserResponse(user.Id, user.Email, 0, user.CreatedAt));
});

app.MapGet("/users/{id:int}", async (int id, AppDbContext db) =>
    await db.Users
        .Where(u => u.Id == id)
        // Projection: selects 4 columns + a COUNT subquery, no tracking, no PasswordHash
        .Select(u => new UserResponse(u.Id, u.Email, u.Orders.Count, u.CreatedAt))
        .FirstOrDefaultAsync() is { } dto ? Results.Ok(dto) : Results.NotFound());

using System.ComponentModel.DataAnnotations;
using System.Text.Json.Serialization;

// Positional record – compact response DTO
public sealed record OrderResponse(
    int Id,
    [property: JsonPropertyName("customer")] string CustomerName,  // attribute on the property
    decimal Total,
    IReadOnlyList<OrderLineResponse> Lines);

public sealed record OrderLineResponse(string Product, int Quantity, decimal UnitPrice);

// Nominal record with required init members – clearer for larger request DTOs
public sealed record CreateProductRequest
{
    [Required, StringLength(100)]
    public required string Name { get; init; }

    [Range(0.01, 100_000)]
    public required decimal Price { get; init; }

    public string? Description { get; init; }
}

// Value equality and non-destructive mutation
var a = new OrderLineResponse("Keyboard", 1, 49.99m);
var b = a with { Quantity = 2 };                         // new instance, a unchanged
Console.WriteLine(a == new OrderLineResponse("Keyboard", 1, 49.99m)); // True
Console.WriteLine(b);  // OrderLineResponse { Product = Keyboard, Quantity = 2, UnitPrice = 49.99 }

public static class OrderMappings
{
    // Expression: EF Core translates it to SQL, so only needed columns are read
    public static readonly Expression<Func<Order, OrderResponse>> ToResponse = o =>
        new OrderResponse(
            o.Id,
            o.Customer.FirstName + " " + o.Customer.LastName,   // flattening
            o.Lines.Sum(l => l.Quantity * l.UnitPrice),
            o.Lines.Select(l => new OrderLineResponse(l.Product.Name, l.Quantity, l.UnitPrice))
                   .ToList());

    // In-memory mapping for an already-loaded entity
    public static OrderLineResponse ToResponse(this OrderLine l) =>
        new(l.Product.Name, l.Quantity, l.UnitPrice);

    // Request -> entity: explicit, so only allowed fields are copied
    public static Order ToEntity(this CreateOrderRequest r, int customerId) => new()
    {
        CustomerId = customerId,
        CreatedAt  = DateTime.UtcNow,
        Lines = r.Lines.Select(x => new OrderLine { ProductId = x.ProductId, Quantity = x.Quantity }).ToList()
    };
}

