public sealed record CreateOrderRequest(
    string CustomerEmail,
    string? CouponCode,
    bool IsGift,
    string? GiftMessage,
    IReadOnlyList<OrderLineRequest> Lines);

public sealed record OrderLineRequest(int ProductId, int Quantity);

public sealed class CreateOrderRequestValidator : AbstractValidator<CreateOrderRequest>
{
    public CreateOrderRequestValidator(ICouponService coupons)
    {
        RuleFor(x => x.CustomerEmail).NotEmpty().EmailAddress().MaximumLength(256);

        RuleFor(x => x.Lines).NotEmpty().WithMessage("An order needs at least one line.");
        RuleForEach(x => x.Lines).ChildRules(line =>
        {
            line.RuleFor(l => l.ProductId).GreaterThan(0);
            line.RuleFor(l => l.Quantity).InclusiveBetween(1, 100);
        });

        // Conditional rule: gift message only required for gifts
        RuleFor(x => x.GiftMessage).NotEmpty().MaximumLength(500).When(x => x.IsGift);

        // Async rule using an injected service
        RuleFor(x => x.CouponCode!)
            .MustAsync((code, ct) => coupons.IsActiveAsync(code, ct))
            .WithMessage("Coupon '{PropertyValue}' is invalid or expired.")
            .When(x => !string.IsNullOrEmpty(x.CouponCode));
    }
}

public sealed class ValidationFilter<T>(IValidator<T> validator) : IEndpointFilter
{
    public async ValueTask<object?> InvokeAsync(EndpointFilterInvocationContext ctx, EndpointFilterDelegate next)
    {
        var dto = ctx.Arguments.OfType<T>().FirstOrDefault();
        if (dto is null)
            return Results.BadRequest();

        var result = await validator.ValidateAsync(dto, ctx.HttpContext.RequestAborted);
        if (!result.IsValid)
            return Results.ValidationProblem(result.ToDictionary()); // RFC 7807 400 response

        return await next(ctx);
    }
}

